#include <stdio.h>
int main(void)
{
  FILE *in, *out;
  int x, n = 0, sum = 0;
  double avg;
  in = fopen("in.txt", "r");
  if (in == NULL) {
    printf("cannot open in.txt\n");
    return 1;
  }
  while (fscanf(in, "%d", &x) == 1) {
    sum += x;
    n++;
  }
  fclose(in);
  out = fopen("out.txt", "w");
  if (out == NULL) {
    printf("cannot open out.txt\n");
    return 1;
  }
  if (n == 0)
    fprintf(out, "no data\n");
  else {
    avg = (double)sum / n;
    fprintf(out, "sum=%d avg=%.2f\n", sum, avg);
  }
  fclose(out);
  return 0;
}

#include <stdio.h>
int main(void)
{
  FILE *in, *out;
  char line[82];
  int n = 0;
  in = fopen("in.txt", "r");
  if (in == NULL) {
    printf("cannot open\n");
    return 1;
  }
  out = fopen("out.txt", "w");
  if (out == NULL) {
    fclose(in);
    printf("cannot open\n");
    return 1;
  }
  while (fgets(line, sizeof(line), in) != NULL) {
    n++;
    fprintf(out, "%d: %s", n, line);
  }
  fclose(in);
  fclose(out);
  printf("%d\n", n);
  return 0;
}
